'use strict';
let toolboxOfflineRegistration=null,toolboxOfflineMessage='',toolboxOfflineBusy=false;
async function toolboxRegisterOffline(){if(!('serviceWorker' in navigator)||!window.isSecureContext||window.Capacitor?.isNativePlatform?.())return;try{toolboxOfflineRegistration=await navigator.serviceWorker.register('sw.js',{updateViaCache:'none'});if(page==='access')render()}catch{toolboxOfflineMessage='Offline download is not available in this browser yet. Keep an internet connection for web access.'}}
function toolboxOfflineCard(){return `<section class="card"><h2>Offline on this device</h2><p>The web app needs internet for its first download. Download all study files before going offline, including the OLP / MLC question banks and source PDFs. Your journals, scores and career records save on the device.</p><button class="btn quiet" data-offline="download" ${toolboxOfflineBusy?'disabled':''}>${toolboxOfflineBusy?'Downloading…':'Download all offline content'}</button><p class="hint">Approximately 40 MB for the complete web app and study sources. Downloads come from the website, not Supabase. An interrupted download can be resumed manually.</p><p id="toolboxOfflineStatus" role="status">${esc(toolboxOfflineMessage||('serviceWorker' in navigator&&window.isSecureContext?'The browser prepares the app files on the first visit. Use the button to prepare every study source.':'Automatic web offline caching needs a supported browser over HTTPS. Packaged native apps use their bundled files.'))}</p>${toolboxOfflineRegistration?.waiting?'<p>A new version is downloaded. Close all Toolbox tabs and reopen to use it. Your saved records are kept.</p>':''}<p class="hint">Browser storage can be cleared or evicted. Keep separate journal and career backups.</p></section>`}
const toolboxOldAccess=accessUI;accessUI=function(){if(cloudEnabled){toolboxOldAccess();app.insertAdjacentHTML('beforeend',toolboxOfflineCard());return}app.innerHTML=`<button class="back" data-nav="settings">← Settings & support</button><header class="learning-heading"><h1>Device storage & optional cloud</h1></header><section class="card"><h2>Your app works without an account</h2><p>Your local profile, journal, reviews, challenge and career tools save on this device. Supabase sign-in and automatic cloud saving are off.</p><p>Career records and document copies have their own backup in Career & documents. Export your journal from Library.</p><button class="text-button" data-nav="learn">Open Library</button> <button class="text-button" data-career="home">Career backups</button></section>${toolboxOfflineCard()}<section class="card"><h2>Cloud upgrade</h2><p>Optional cloud backup and syncing will require an explicit upgrade. Payments and subscription access checks are not connected yet. Using the web link does not purchase an upgrade.</p><button class="btn quiet" disabled>Cloud upgrade coming soon</button><details><summary>Existing cloud account</summary><p>If you already used Toolbox Cloud, you can explicitly open its existing sign-in to retrieve those records. Your offline workspace and career files remain separate. This does not purchase a subscription or upload your offline workspace.</p><button class="text-button" data-offline="existingCloud" ${hubConfig.supabaseUrl&&hubConfig.publishableKey?'':'disabled'}>Open existing cloud sign-in</button></details></section>`};
const toolboxOldCloudPlan=learningCloudPlan;learningCloudPlan=function(){app.innerHTML='<header class="learning-heading"><h1>Optional Toolbox Cloud</h1></header><section class="card"><h2>Offline comes first.</h2><p>Use Toolbox on this device without creating an account. A future cloud upgrade will add online backup and syncing. No payment or subscription purchase is connected yet.</p><button class="btn quiet" disabled>Cloud upgrade coming soon</button><p><button class="text-button" data-nav="access">Device storage & existing cloud access</button></p></section>'};
const toolboxOldProfileLinks=profileLinks;profileLinks=function(){return toolboxOldProfileLinks()+`<section class="card"><button class="profile-action" data-nav="access"><span>Offline storage & downloads</span><small>Open</small></button></section>`};
if(!cloudEnabled)crewSetupStages[1]=['Contact email (optional)','Add it for your CV, or leave it blank. No account is created.',['email']];
const toolboxOldProfile=profile;profile=function(setup=false){toolboxOldProfile(setup);if(!cloudEnabled){const field=app.querySelector('#qaProfileForm input[name="email"]');if(field){field.required=false;field.removeAttribute('required')}const note=app.querySelector('.profile-email-note');if(note)note.textContent='Optional contact detail for this device. No sign-in or cloud account is created.'}};
const toolboxOldCloudAuthView=cloudAuthView;cloudAuthView=function(){toolboxOldCloudAuthView();app.insertAdjacentHTML('beforeend','<p><button class="btn quiet" data-offline="local">Use my offline workspace</button></p>')};
async function toolboxOfflinePack(){if(toolboxOfflineBusy)return;toolboxOfflineBusy=true;toolboxOfflineMessage='Preparing the offline download…';render();try{if(!toolboxOfflineRegistration)await toolboxRegisterOffline();const worker=toolboxOfflineRegistration?.active;if(!worker)throw Error('The offline app is still installing. Wait for installation, then try again.');const channel=new MessageChannel();await new Promise((resolve,reject)=>{channel.port1.onmessage=e=>{const m=e.data;if(m.type==='progress'){toolboxOfflineMessage=`Downloaded ${m.done} of ${m.total} study files.`;const s=document.getElementById('toolboxOfflineStatus');if(s)s.textContent=toolboxOfflineMessage}if(m.type==='complete'){channel.port1.close();resolve()}if(m.type==='error'){channel.port1.close();reject(Error(m.message))}};worker.postMessage({type:'DOWNLOAD_ALL'},[channel.port2])});toolboxOfflineMessage='All app and study files are available offline on this device.'}catch(e){toolboxOfflineMessage=e.message}finally{toolboxOfflineBusy=false;if(page==='access')render()}}
document.addEventListener('click',e=>{const b=e.target.closest?.('button[data-offline]');if(!b||b.disabled)return;e.preventDefault();e.stopImmediatePropagation();if(b.dataset.offline==='download'){void toolboxOfflinePack();return}if(b.dataset.offline==='existingCloud'){if(!hubConfig.supabaseUrl||!hubConfig.publishableKey)return;try{localStorage.setItem('toolbox-cloud-choice-v1','enabled');location.reload()}catch{toast('Could not change this device preference.')}}if(b.dataset.offline==='local'){try{if(cloudEnabled&&cloudUser){if(cloudPending&&!cloudWriteBackup()){toast('Device backup failed. Resolve the save before changing workspace.');return}clearTimeout(cloudTimer);clearTimeout(cloudRetryTimer)}localStorage.removeItem('toolbox-cloud-choice-v1');location.reload()}catch{toast('Could not change this device preference.')}}},true);
// No polling or Supabase calls. The worker caches only same-origin public app files.
void toolboxRegisterOffline();
